coding.solution:
def find_boundary_bugs(is_valid, low, high):
    bugs = []
    for x in sorted({low - 1, low, high, high + 1}):
        expected = low <= x <= high
        if bool(is_valid(x)) != expected:
            bugs.append(x)
    return bugs
